import { dismiss, toasts, type ToastKind } from '../app/notify.ts';
import { t } from '../app/i18n.ts';

/**
 * A translated sentence with a little markup in it: <b>…</b>, <code>…</code> and <a>…</a>, whose addresses are
 * given in order in `links` (they open in a new tab).
 */
export function Rich({ text, links = [] }: { text: string; links?: string[] }) {
  const out: ComponentChildren[] = [];
  const re = /<(b|code|a)>(.*?)<\/\1>/g;
  let at = 0;
  let li = 0;
  for (let m = re.exec(text); m; m = re.exec(text)) {
    if (m.index > at) out.push(text.slice(at, m.index));
    if (m[1] === 'b') out.push(<b>{m[2]}</b>);
    else if (m[1] === 'code') out.push(<code>{m[2]}</code>);
    else
      out.push(
        <a href={links[li++]} target="_blank" rel="noopener">
          {m[2]} <ExternalLink size={12} />
        </a>,
      );
    at = re.lastIndex;
  }
  if (at < text.length) out.push(text.slice(at));
  return <>{out}</>;
}

export function Sheet(props: {
  title: string;
  icon?: ComponentChildren;
  onClose: () => void;
  wide?: boolean;
  tabs?: ComponentChildren;
  children: ComponentChildren;
  label?: string;
}) {
  // the latest onClose, without reinstalling the listener at every render (callers pass a new arrow each time)
  const close = useRef(props.onClose);
  close.current = props.onClose;
  // as soon as it is on screen (an effect waits for the next frame: an Escape pressed at once was missed)
  useLayoutEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close.current();
    };
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, []);
  return (
    <>
      <div class="scrim" onClick={props.onClose} />
      <section
        class={`sheet ${props.wide ? 'wide' : ''}`}
        role="dialog"
        aria-modal="true"
        aria-label={props.label ?? props.title}
      >
        <div>
          <header class="sheet-head">
            {props.icon && <div class="big-ico">{props.icon}</div>}
            <h2>{props.title}</h2>
            <button class="icon-btn" onClick={props.onClose} aria-label={t('Close')}>
              <X />
            </button>
          </header>
          {props.tabs}
        </div>
        <div class="sheet-body">{props.children}</div>
      </section>
    </>
  );
}

export function Switch(props: { checked: boolean; onChange: (v: boolean) => void; label: string }) {
  return (
    <button
      type="button"
      role="switch"
      class="switch"
      aria-checked={props.checked}
      aria-label={props.label}
      onClick={(e) => {
        e.stopPropagation();
        props.onChange(!props.checked);
      }}
    />
  );
}

export function ToggleRow(props: {
  title: string;
  sub?: ComponentChildren;
  checked: boolean;
  onChange: (v: boolean) => void;
  disabled?: boolean;
}) {
  return (
    <div
      class="row-toggle"
      style={props.disabled ? 'opacity:.5;pointer-events:none' : undefined}
      onClick={() => props.onChange(!props.checked)}
    >
      <div class="grow">
        <div class="row-title">{props.title}</div>
        {props.sub && <div class="row-sub">{props.sub}</div>}
      </div>
      <Switch checked={props.checked} onChange={props.onChange} label={props.title} />
    </div>
  );
}

export function Seg<T extends string | number>(props: {
  value: T;
  options: { value: T; label: ComponentChildren; title?: string }[];
  onChange: (v: T) => void;
  label: string;
  disabled?: boolean;
}) {
  return (
    <div class="seg" role="group" aria-label={props.label}>
      {props.options.map((o) => (
        <button
          type="button"
          aria-pressed={o.value === props.value}
          title={o.title}
          disabled={props.disabled}
          onClick={() => props.onChange(o.value)}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

/** A <video> showing a stream (muted: sound plays from separate audio elements). */
export function VideoView(props: {
  stream: MediaStream | null;
  class?: string;
  onResize?: (w: number, h: number) => void;
}) {
  const ref = useRef<HTMLVideoElement>(null);
  useEffect(() => {
    const v = ref.current;
    if (!v) return;
    if (v.srcObject !== props.stream) v.srcObject = props.stream;
    if (props.stream) void v.play().catch(() => {});
  }, [props.stream]);
  return (
    <video
      ref={ref}
      class={props.class}
      autoplay
      playsInline
      muted
      disablePictureInPicture={false}
      onResize={(e) => {
        const v = e.currentTarget as HTMLVideoElement;
        props.onResize?.(v.videoWidth, v.videoHeight);
      }}
    />
  );
}

/** Level bars (0..1). */
/**
 * Level bars (0..1). The level changes at every frame: only this small component follows it, and only when the
 * number of lit bars changes (the components around it do not re-render with the meter).
 */
export function LevelBars({
  level,
  clipping,
  n = 5,
  on = true,
}: {
  level: ReadonlySignal<number>;
  clipping?: ReadonlySignal<boolean>;
  n?: number;
  on?: boolean;
}) {
  const litSig = useComputed(() => (on ? Math.round(level.value * n * 1.15) : 0));
  const clipSig = useComputed(() => !!clipping?.value);
  const lit = litSig.value;
  const clip = clipSig.value;
  return (
    <span class="bars" aria-hidden="true">
      {Array.from({ length: n }, (_, i) => (
        <i
          style={{ height: `${30 + (i * 70) / (n - 1)}%` }}
          class={i < lit ? (clip && i >= n - 2 ? 'clip' : i >= n - 1 ? 'hot' : 'on') : ''}
        />
      ))}
    </span>
  );
}

const qualityLabel = (q: 'good' | 'fair' | 'poor' | 'unknown') =>
  ({ good: t('Good connection'), fair: t('Fair connection'), poor: t('Poor connection'), unknown: t('Connection') })[q];

export function SignalBars({ quality }: { quality: 'good' | 'fair' | 'poor' | 'unknown' }) {
  return (
    <span class={`signal ${quality}`} aria-label={qualityLabel(quality)}>
      <i />
      <i />
      <i />
    </span>
  );
}

/** QR code with rounded modules, drawn as SVG. */
export function Qr({ text }: { text: string }) {
  const svg = useMemo(() => {
    const { data, size } = encode(text, { ecc: 'M', border: 0 });
    const parts: string[] = [];
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (data[y][x]) parts.push(`M${x + 0.08} ${y + 0.08}h0.84v0.84h-0.84z`);
      }
    }
    return { d: parts.join(''), size };
  }, [text]);
  return (
    <div class="qr" role="img" aria-label={t('QR code of the room link')}>
      <svg viewBox={`0 0 ${svg.size} ${svg.size}`} shape-rendering="geometricPrecision">
        <path d={svg.d} fill="#17141c" />
      </svg>
    </div>
  );
}

const TOAST_ICONS: Record<ToastKind, typeof Info> = {
  info: Info,
  join: LogIn,
  leave: LogOut,
  warn: TriangleAlert,
  error: CircleAlert,
  success: Check,
  knock: DoorOpen,
  chat: MessageSquare,
};

export function Toasts() {
  const list = toasts.value;
  return (
    <div class="toasts" aria-live="polite">
      {list.map((item) => {
        const Ico = TOAST_ICONS[item.kind];
        return (
          <div class={`toast ${item.kind}`} key={item.id} role="status">
            <div class="t-ico">
              <Ico />
            </div>
            <div class="grow">
              <b>{item.title}</b>
              {item.body && <small>{item.body}</small>}
            </div>
            {item.action && (
              <button
                class="btn btn-sm btn-primary"
                onClick={() => {
                  item.action!.run();
                  dismiss(item.id);
                }}
              >
                {item.action.label}
              </button>
            )}
            <button
              class="icon-btn"
              style="width:28px;height:28px"
              onClick={() => dismiss(item.id)}
              aria-label={t('Dismiss')}
            >
              <X size={16} />
            </button>
          </div>
        );
      })}
    </div>
  );
}

/** Copy text, with a fallback for browsers without the async clipboard. */
export async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    let ok = false;
    try {
      ok = document.execCommand('copy');
    } catch {
      ok = false;
    }
    ta.remove();
    return ok;
  }
}
