// The 88 keys: what everyone plays lights up in their role colour (and the sustain pedals). The keys can be
// played with the mouse, touch, or the computer keyboard; they sound on the built-in piano and reach the others.

import { useEffect, useMemo, useRef, useState } from 'preact/hooks';
import { Keyboard as KeyboardIcon, X } from 'lucide-preact';
import { session } from '../app/session.ts';
import { settings, updateMidi } from '../app/settings.ts';
import { isTouch } from '../app/platform.ts';
import { lang, t, type Lang } from '../app/i18n.ts';

const LOW = 21;
const HIGH = 108;
const BLACK = new Set([1, 3, 6, 8, 10]);
const NAMES = ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'];
/** the names musicians use in each language: solfège in the Romance languages, H for B in German */
const NAMES_BY: Partial<Record<Lang, string[]>> = {
  fr: ['do', 'do♯', 'ré', 'ré♯', 'mi', 'fa', 'fa♯', 'sol', 'sol♯', 'la', 'la♯', 'si'],
  es: ['do', 'do♯', 're', 're♯', 'mi', 'fa', 'fa♯', 'sol', 'sol♯', 'la', 'la♯', 'si'],
  it: ['do', 'do♯', 're', 're♯', 'mi', 'fa', 'fa♯', 'sol', 'sol♯', 'la', 'la♯', 'si'],
  pt: ['dó', 'dó♯', 'ré', 'ré♯', 'mi', 'fá', 'fá♯', 'sol', 'sol♯', 'lá', 'lá♯', 'si'],
  de: ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'H'],
};
/** French and Italian count the octaves from one lower (middle C is do3) */
const LOWER_OCTAVE = new Set<Lang>(['fr', 'it']);

/** A note's name: C4 for middle C in English, do3 in French and Italian, do4 in Spanish, C4 in German. */
export function noteName(note: number): string {
  const l = lang.value;
  const octave = Math.floor(note / 12) - 1 - (LOWER_OCTAVE.has(l) ? 1 : 0);
  return `${(NAMES_BY[l] ?? NAMES)[note % 12]}${octave}`;
}

/** Computer keys -> semitones from the octave's C (by physical position: works on AZERTY and QWERTZ too). */
const QWERTY: Record<string, number> = {
  KeyA: 0,
  KeyW: 1,
  KeyS: 2,
  KeyE: 3,
  KeyD: 4,
  KeyF: 5,
  KeyT: 6,
  KeyG: 7,
  KeyY: 8,
  KeyH: 9,
  KeyU: 10,
  KeyJ: 11,
  KeyK: 12,
  KeyO: 13,
  KeyL: 14,
  KeyP: 15,
  Semicolon: 16,
  Quote: 17,
};

interface KeyGeom {
  note: number;
  black: boolean;
  left: number;
  width: number;
}

function layout(): KeyGeom[] {
  let whites = 0;
  for (let n = LOW; n <= HIGH; n++) if (!BLACK.has(n % 12)) whites++;
  const w = 100 / whites;
  const out: KeyGeom[] = [];
  let wi = 0;
  for (let n = LOW; n <= HIGH; n++) {
    if (BLACK.has(n % 12)) {
      // black keys sit a little off-centre, as on a real keyboard
      const pc = n % 12;
      const shift = pc === 1 || pc === 6 ? -0.12 : pc === 3 || pc === 10 ? 0.12 : 0;
      out.push({ note: n, black: true, left: (wi + shift) * w - w * 0.31, width: w * 0.62 });
    } else {
      out.push({ note: n, black: false, left: wi * w, width: w });
      wi++;
    }
  }
  return out;
}

function typingTarget(t: EventTarget | null): boolean {
  const el = t as HTMLElement | null;
  return (
    !!el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT' || el.isContentEditable)
  );
}

export function PianoKeys({ onClose }: { onClose: () => void }) {
  const keys = useMemo(layout, []);
  const hub = session.midi;
  void hub.version.value; // redraw on every change
  const peers = session.peers.value;
  const s = settings.value;
  const qwerty = s.midi.qwerty;
  const [octave, setOctave] = useState(4);
  // read by the key handlers as it is now (changing octave must not reinstall them and cut held notes)
  const octaveRef = useRef(octave);
  octaveRef.current = octave;
  const pointers = useRef(new Map<number, number>());
  const box = useRef<HTMLDivElement>(null);
  const pedals = hub.sustainHeld();
  const roleOf = (id: string | null) => peers.find((p) => p.id === id)?.info.role ?? 'player';

  // the keys are out: get the piano's sound ready
  useEffect(() => {
    void hub.piano.load();
  }, []);
  const loaded = hub.piano.loaded.value;
  const total = hub.piano.total.value;
  const loading = !hub.piano.ready.value && !hub.piano.failed.value && total > 0;

  const play = (note: number, vel: number) => {
    hub.piano.context();
    void hub.piano.load();
    hub.fromScreen([0x90, note, vel]);
  };
  const stop = (note: number) => hub.fromScreen([0x80, note, 64]);

  // computer keyboard
  useEffect(() => {
    if (!qwerty) return;
    const held = new Map<string, number>();
    let pedal = false;
    const down = (e: KeyboardEvent) => {
      if (e.repeat || e.metaKey || e.ctrlKey || e.altKey || typingTarget(e.target)) return;
      if (e.code === 'KeyZ') return setOctave((o) => Math.max(1, o - 1));
      if (e.code === 'KeyX') return setOctave((o) => Math.min(7, o + 1));
      if (e.code === 'Space') {
        e.preventDefault();
        pedal = true;
        hub.fromScreen([0xb0, 64, 127]);
        return;
      }
      const semi = QWERTY[e.code];
      if (semi === undefined || held.has(e.code)) return;
      const note = 12 * (octaveRef.current + 1) + semi;
      if (note < LOW || note > HIGH) return;
      held.set(e.code, note);
      play(note, 92);
    };
    const up = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        pedal = false;
        hub.fromScreen([0xb0, 64, 0]);
        return;
      }
      const note = held.get(e.code);
      if (note === undefined) return;
      held.delete(e.code);
      stop(note);
    };
    // the window loses the keys (another app, the keys closed): their key-ups will never come
    const blur = () => {
      for (const n of held.values()) stop(n);
      held.clear();
      if (pedal) hub.fromScreen([0xb0, 64, 0]);
      pedal = false;
    };
    window.addEventListener('keydown', down);
    window.addEventListener('keyup', up);
    window.addEventListener('blur', blur);
    return () => {
      blur();
      window.removeEventListener('keydown', down);
      window.removeEventListener('keyup', up);
      window.removeEventListener('blur', blur);
    };
  }, [qwerty]);

  const noteAt = (x: number, y: number): { note: number; vel: number } | null => {
    const el = document.elementFromPoint(x, y) as HTMLElement | null;
    const n = el?.dataset.note;
    if (!n || !box.current) return null;
    const r = box.current.getBoundingClientRect();
    const depth = Math.max(0, Math.min(1, (y - r.top) / r.height));
    return { note: Number(n), vel: Math.round(48 + depth * 70) };
  };

  return (
    <section class="keys" aria-label={t('Piano keyboard')} data-testid="keyboard">
      <div class="keys-head">
        <span class="legend" data-role="self">
          <i /> {t('You')}
        </span>
        {peers.map((p) => (
          <span class="legend" data-role={p.info.role}>
            <i /> {p.info.name}
          </span>
        ))}
        <span class={`pedal ${pedals.local ? 'on' : ''}`} data-role="self" title={t('Your sustain pedal')}>
          {t('Pedal')}
        </span>
        {peers.length > 0 && (
          <span
            class={`pedal remote ${pedals.remote ? 'on' : ''}`}
            data-role={roleOf([...hub.remote.keys()][0] ?? null)}
            title={t('Their sustain pedal')}
          >
            {t('Their pedal')}
          </span>
        )}
        <span style="flex:1" />
        {loading && (
          <span class="keys-loading" role="status">
            {t('Loading the grand piano · {pct}%', { pct: Math.round((loaded / total) * 100) })}
          </span>
        )}
        {!isTouch && (
          <button
            class={`btn btn-sm ${qwerty ? 'btn-primary' : 'btn-ghost'}`}
            onClick={() => updateMidi({ qwerty: !qwerty })}
            title={t(
              'Play with the computer keyboard: A W S E D F T G Y H U J K, Z / X change octave, Space is the pedal',
            )}
          >
            <KeyboardIcon />{' '}
            {qwerty
              ? t('Computer keys on · {note}', { note: noteName(12 * (octave + 1)) })
              : t('Play with computer keys')}
          </button>
        )}
        <button class="icon-btn" style="width:30px;height:30px" onClick={onClose} aria-label={t('Hide keyboard')}>
          <X size={16} />
        </button>
      </div>
      <div
        class="keyboard"
        ref={box}
        onPointerDown={(e) => {
          const hit = noteAt(e.clientX, e.clientY);
          if (!hit) return;
          (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
          pointers.current.set(e.pointerId, hit.note);
          play(hit.note, hit.vel);
        }}
        onPointerMove={(e) => {
          const cur = pointers.current.get(e.pointerId);
          if (cur === undefined) return;
          const hit = noteAt(e.clientX, e.clientY);
          if (!hit || hit.note === cur) return;
          stop(cur);
          pointers.current.set(e.pointerId, hit.note);
          play(hit.note, hit.vel);
        }}
        onPointerUp={(e) => {
          const cur = pointers.current.get(e.pointerId);
          if (cur !== undefined) stop(cur);
          pointers.current.delete(e.pointerId);
        }}
        onPointerCancel={(e) => {
          const cur = pointers.current.get(e.pointerId);
          if (cur !== undefined) stop(cur);
          pointers.current.delete(e.pointerId);
        }}
      >
        {keys.map((k) => {
          const h = hub.holder(k.note);
          const on = h.local || !!h.remote;
          const role = h.local ? 'self' : roleOf(h.remote);
          const name = noteName(k.note);
          return (
            <div
              key={k.note}
              data-note={k.note}
              class={`${k.black ? 'bkey' : 'wkey'} ${on ? 'on' : ''} ${k.note === 60 ? 'middle-c' : ''}`}
              style={{ left: `${k.left}%`, width: `${k.width}%` }}
              data-role={on ? role : undefined}
              aria-label={name}
              data-on={on || undefined}
            >
              {!k.black && k.note % 12 === 0 && <span class="lbl">{name}</span>}
            </div>
          );
        })}
      </div>
    </section>
  );
}
